mapper.select:
SELECT sa.id, sa.student_id AS studentId, sa.student_name AS studentName, sa.course_id AS courseId, sa.course_name AS courseName, sa.prev_score AS prevScore, sa.curr_score AS currScore, sa.drop_score AS dropScore, sa.alert_level AS alertLevel, sa.status, sa.semester, sa.handle_remark AS handleRemark, sa.create_time AS createTime, sa.update_time AS updateTime, s.student_no AS studentNo FROM score_alert sa LEFT JOIN student s ON sa.student_id = s.id
AND sa.status = #{status}
AND sa.alert_level = #{alertLevel}
AND sa.student_name LIKE CONCAT('%', #{studentName}, '%')
ORDER BY sa.create_time DESC
